package operator

import (
	"context"
	"time"

	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/internal/errorx"
	"github.com/garamsh/garam/internal/grn"
	"github.com/garamsh/garam/internal/operator/db"
	"github.com/garamsh/garam/internal/pgxerr"
)

// PostgresStore implements Store against PostgreSQL. The queries are
// generated by sqlc from queries.sql.
type PostgresStore struct {
	q *db.Queries
}

// Compile-time check that PostgresStore satisfies Store.
var _ Store = (*PostgresStore)(nil)

// NewPostgresStore constructs a Postgres-backed Store.
func NewPostgresStore(pool *pgxpool.Pool) *PostgresStore {
	return &PostgresStore{q: db.New(pool)}
}

// Register persists the record.
func (s *PostgresStore) Register(ctx context.Context, o *Operator) error {
	err := s.q.CreateOperator(ctx, db.CreateOperatorParams{
		Grn:          o.grn.String(),
		OrgGrn:       o.orgGRN.String(),
		RegisteredBy: o.registeredBy.String(),
		CreatedAt:    stamp(o.createdAt),
	})
	return pgxerr.Classify(err, "register operator", nil, ErrOperatorAlreadyRegistered)
}

// Get returns the organization's record of the operator.
func (s *PostgresStore) Get(ctx context.Context, g grn.GRN) (*Operator, error) {
	row, err := s.q.GetOperator(ctx, g.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "get operator", ErrOperatorNotFound, nil)
	}
	return rowToOperator(row)
}

// ListByOrg returns the organization's operators.
func (s *PostgresStore) ListByOrg(ctx context.Context, orgGRN grn.GRN) ([]*Operator, error) {
	rows, err := s.q.ListOperatorsByOrg(ctx, orgGRN.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "list operators", nil, nil)
	}
	operators := make([]*Operator, 0, len(rows))
	for _, row := range rows {
		o, err := rowToOperator(row)
		if err != nil {
			return nil, err
		}
		operators = append(operators, o)
	}
	return operators, nil
}

// rowToOperator converts a sqlc row into the domain aggregate. A stored
// GRN that no longer parses is data corruption, hence internal.
func rowToOperator(row db.Operator) (*Operator, error) {
	g, err := grn.Parse(row.Grn)
	if err != nil {
		return nil, errorx.Wrap(err, "grn", errorx.KindInternal)
	}
	orgGRN, err := grn.Parse(row.OrgGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "org grn", errorx.KindInternal)
	}
	if err := validateOwnership(g, orgGRN); err != nil {
		return nil, errorx.Wrap(err, "stored operator", errorx.KindInternal)
	}
	registeredBy, err := grn.Parse(row.RegisteredBy)
	if err != nil {
		return nil, errorx.Wrap(err, "registered by", errorx.KindInternal)
	}
	return &Operator{
		grn:          g,
		orgGRN:       orgGRN,
		registeredBy: registeredBy,
		createdAt:    row.CreatedAt.Time,
	}, nil
}

// stamp converts a time.Time to a valid pgtype.Timestamptz.
func stamp(t time.Time) pgtype.Timestamptz {
	return pgtype.Timestamptz{Time: t, Valid: true}
}
